  "測る": "measure",
  "A(見たい状態、例 ヤンデレの system)と B(中立)の応答のトークンで、各ニューロンが残差に書き足した量(活性の差 × 書く向き)を測る。寄与は、参照の層の A − B の方向 r* への直接の成分。活性の差だけを見る「読み手」と違い、方向に実際に書いているものが上に来る。": "On the response tokens of A (the state you want, e.g. a yandere system prompt) and B (neutral), measures how much each neuron wrote into the residual (activation difference × write direction). The contribution is the direct component along the A − B direction r* at the reference layer. Unlike activation differences alone (readers), the neurons that actually write the direction come out on top.",
