  "greedy は毎回いちばん確率の高い語を選ぶ(同じ入力なら毎回同じ応答)。サンプリングは llama.cpp と同じ順番(presence penalty → top-k → top-p → min-p → 温度)で、3 列とも同じ乱数で引くので、違いは介入の違いだけ": "Greedy always picks the most likely token (the same input always gives the same response). Sampling follows llama.cpp's order (presence penalty → top-k → top-p → min-p → temperature), and all three columns draw the same random numbers, so the only difference is the steering",
