  "線形注意(Gated DeltaNet など)の層には softmax の注目のパターンがありません。Details の W_O ブロックの lens と、Contrast の出力の差(out_shift・dir_cos)で見てください。": "Linear-attention layers (Gated DeltaNet etc.) have no softmax attention pattern. Use the W_O block lens in Details and the output metrics (out_shift, dir_cos) in Contrast.",
  "文章を入れて「流す」(このヘッドがどのトークンを見ているか)": "Enter text and press Run (which tokens this head looks at)",
  "文章をユーザーの発話としてチャットテンプレートに入れる": "Put the text into the chat template as the user turn",
  "チャットの形": "as chat",
  "同じユーザーの発話を system あり/なしで流し、共通の末尾で注目の差を見る": "Run the same user turn with and without the system prompt and compare attention over the shared tail",
  "ペルソナあり/なしを比べる": "compare persona on / off",
  "ペルソナ(system)。空なら system なし": "Persona (system prompt). Empty = no system prompt",
  "トリガー(カンマ区切り、re: で正規表現)": "Triggers (comma-separated, re: for a regex)",
  "{a} / {b} トークン · 共通の末尾 {s}": "{a} / {b} tokens · shared tail {s}",
  "{n} トークン": "{n} {n|token|tokens}",
  "このヘッドのパターンを捕捉できませんでした": "Could not capture this head's pattern",
  "差 = ペルソナあり − なし(共通の末尾の行と列。左端の列は末尾より前 = system への注目の合計)。黄 = ありで増えた、赤紫 = 減った。明るさ = √(|差| / 最大 {m})": "Difference = persona on − off (rows and columns of the shared tail; the leftmost column is the total attention to everything before it = the system part). Yellow = more with the persona, magenta = less. Brightness = √(|diff| / max {m})",
  "行 = 見ている位置、列 = 見られている位置(右上は因果マスクで 0)。明るさ = √(注目の重み)、0〜1": "Row = attending position, column = attended position (the upper right is 0 under the causal mask). Brightness = √(attention weight), 0–1",
  "ペルソナあり": "persona on",
  "差(共通の末尾)": "difference (shared tail)",
  "マウスを当てると、その行と列のトークンと値": "Hover for the row and column tokens and the value",
  "水色の印 = トリガーの列": "Cyan marks = trigger columns",
  "トリガーが文章の中に見つかりません": "No trigger found in the text",
  "トリガー": "trigger",
  "最後の行(あり / なし / 差)": "last row (on / off / diff)",
  "後ろの行の平均(あり / なし / 差)": "mean of later rows (on / off / diff)",
  "最後の行": "last row",
  "後ろの行の平均": "mean of later rows",
  "トリガー区間への注目(共通部分の中の割合)": "Attention to trigger spans (share within the shared part)",
  "割合 = その行の注目のうち、トリガーのトークンへのもの(比べるときは system の部分を除いた共通部分の中で。gne heads contrast の trigger_mass と同じ分母)。最後の行 = 応答の最初のトークンを決める位置。": "Share = the part of a row's attention that goes to the trigger tokens (when comparing, within the shared part without the system prompt — the same denominator as trigger_mass in gne heads contrast). Last row = the position that picks the response's first token.",
  "行": "row",
  "列": "col",
  "(未来は見えない)": "(future: masked)",
  "このヘッドを含むヘッドの対照分析はまだありません({cmd})。": "No head contrast includes this head yet ({cmd}).",
  "地図の板の上辺のヘッドをこの対照分析の z で色付けする": "Color the heads on the map by this contrast's z",
  "地図で見る": "show on map",
  "指標": "metric",
  "値": "value",
  "中立どうし(system を別の中立の文に替えただけ)で測った同じ指標の、全ヘッドの 95% 点": "95th percentile over all heads of the same metric measured neutral vs neutral (only the system prompt swapped for another neutral one)",
  "基準値(中立どうしの差の p95)": "baseline (p95 of neutral-pair differences)",
  "方向 {d}": "direction {d}",
  "トリガーのある会話(Pattern で、このヘッドの注目をペルソナあり/なしで見る)": "Conversations with triggers (open in Pattern to compare this head's attention with the persona on / off)",
  "Pattern で見る": "open in Pattern",
  "この対照分析の上位": "Top heads in this contrast",
  "大きさ": "shape",
  "書き込み": "writes via",
  "W_O の列ブロックの logit lens(主成分 1 本目の割合 {p})": "Logit lens of the W_O column block (first component's share {p})",
  "このヘッドが残差に書ける向き(W_O の列ブロック)を特異値分解し、主成分を出力層に通したときに上がる語(+)と下がる語(−)。主成分の符号は任意なので、+ と − は入れ替わりうる。": "SVD of the directions this head can write to the residual (its W_O column block); each principal component passed through the output layer, with the tokens it raises (+) and lowers (−). A component's sign is arbitrary, so + and − may be swapped.",
  "このヘッドの gain はまだ当てていません(上の「×0 レシピ」「×2 レシピ」から 3 列チャットや eval で試せます)": "No gain tried on this head yet (add it with \"×0 recipe\" / \"×2 recipe\" above and try it in the 3-column chat or eval)",
  "ヘッドの対照分析": "head contrast",
  "+ 反応性": "+ reactivity",
  "ヘッドの対照 {d} の z": "head contrast {d}: z",
  "ヘッドの注目(fires の選んだトークンへ)": "head attention (to the chosen fires token)",
  "対照の 95% 以下": "≤ controls' 95th pct",
  "z {a}〜{b}(対照の 95% 超)": "z {a}–{b} (above controls' 95th pct)",
  "色 = 板の上辺のヘッドの帯": "color = head strip on top of each board",
  "注目 0〜{m}(後ろの位置からの平均、明るさ = √)": "attention 0–{m} (mean over later positions, brightness = √)",
  "線形注意の層はパターンが無いので色なし": "linear-attention layers have no pattern (uncolored)",
  "ヘッドの倍率 k は 1 が無介入(0 で消す、2 で倍、負で反転)。LoRA で当てるので cvec には入りません。3 列チャットの − 列は 1 の反対側(×0 なら ×2)。": "A head's factor k: 1 = no change (0 removes it, 2 doubles it, negative flips it). Applied as a LoRA, so it is not part of the cvec. In the 3-column chat the − column mirrors it around 1 (×0 becomes ×2).",
  "HEAD パネルで開く": "Open in the HEAD panel",
  "HEAD を広げる・戻す": "Widen / restore the HEAD panel",
  "マップの板の上辺の刻み(ヘッド)をクリック。jump に L21 H7 でも開けます": "Click a tick on top of a board (a head) on the map, or type L21 H7 in jump",
  "{s} 秒の音声": "{s} s of audio",
  "空なら無し(音声で話すなら Respond in text.)": "empty = none (for speech: Respond in text.)",
  "右の列の応答を、ブラウザの音声で読み上げる": "Read the right column's response aloud with the browser's voice",
  "読み上げ": "read aloud",
  "音声で話しかける(押して話し、もう一度押すと送る。入力欄の文も一緒に送る)": "Talk by voice (press, speak, press again to send; any text in the box goes along)",
  "止めて送る": "stop & send",
  "話す": "talk",
  "このページではマイクを使えません(http://127.0.0.1 か localhost で開いてください)": "The microphone is not available on this page (open it at http://127.0.0.1 or localhost)",
