  "線形注意の層には softmax の注目がないので、Listen は使えません。": "Linear-attention layers have no softmax attention, so Listen does not apply.",
  "色 = そのトークンの方向への寄与(応答のトークンの平均)。黄 = 方向の向き、赤紫 = 逆向き。明るさ = √(|値| / 文脈の最大)。": "Color = the token's contribution along the direction (mean over response tokens). Yellow = along the direction, magenta = against it. Brightness = √(|value| / context max).",
  "色 = 応答の各トークンからの注目の平均(選んだヘッドの合計)。明るさ = √(値 / 文脈の最大)。": "Color = mean attention from the response tokens (summed over the chosen heads). Brightness = √(value / context max).",
