  "B ⊥(B 側の直交成分のずれ)": "B ⊥ (B-side orthogonal drift)",
  "B 側(関係のない入力)の残差の差のうち方向に直交する成分。小さいほど他を壊さない": "Component of the B-side (unrelated inputs) residual change orthogonal to the direction. Smaller = breaks less of everything else",
  "B 側の変化が上限を超えたので配分から外した": "Excluded from the allocation: the B-side change exceeded the limit",
  "B 側の変化が大きく外した": "excluded: large B-side change",
  "B 側の残差の直交成分のずれ": "Orthogonal drift of the B-side residual",
