  "B 側の直交成分のずれが対照の何割より大きいか(大きいほど他を壊している)": "Share of the controls whose B-side orthogonal drift this exceeds (higher = breaks more of everything else)",
  "L{L} H{h} はこのスクリーニングで測っていません(層単位のスクリーニングで選ばれた層のヘッドだけを測ります)。": "L{L} H{h} was not measured in this screening (only heads in the layers picked by the layer-level screening are measured).",
  "L{L} の例ごとの射影の値(残差 · r̂_L、最後のトークン)": "Per-example projections at L{L} (residual · r̂_L, last token)",
  "L{L} の射影のヘッドの方向が {n} 種類あるので、LoRA の階数は {n}(同じ方向なら 1 に畳める)": "The projected heads in L{L} use {n} different directions, so the LoRA has rank {n} (one shared direction folds to rank 1)",
  "L{L} の射影のヘッドはどれも同じ方向なので、LoRA は階数 1 に畳める": "All projected heads in L{L} share one direction, so the LoRA folds to rank 1",
  "L{L} の射影の値を {v} まで": "L{L} projection down to {v}",
  "L{L} を基準層にする": "Make L{L} the base layer",
  "causal ÷ 直接の寄与(表示中の測る層)": "causal ÷ direct contribution (at the measured layer shown)",
  "causal ÷ 直接の寄与。1 より大きい = 後段のユニットを通る間接の経路、1 より小さい = 補い合い": "causal ÷ direct contribution. Above 1 = indirect paths through later units, below 1 = compensation",
  "cohen_d が最大の層": "layer with the largest cohen_d",
  "cohen_d 最大": "largest cohen_d",
  "cohen_d(A と B の射影の値の離れ方、左の目盛り)": "cohen_d (separation of the A and B projections, left axis)",
  "x = ヘッドの数(gne heads allocate の組)。少ないヘッドほど 1 ヘッドの s が大きくなる。残り = 目標に届かず残った効きにくい例の数。白の破線 = 推奨の組。": "x = number of heads (the gne heads allocate sets). Fewer heads means a larger s per head. Remaining = hard examples still above the target. White dashed line = recommended set.",
  "{s} 秒 · A {a} / B {b} 例": "{s} s · A {a} / B {b} examples",
  "η = いまの組から s を Δs 上げたときの、効きにくい例での下がり方 ÷ Δs(L{L})。対照の z とは別物": "η = drop on the hard examples when s is raised by Δs from the current set, ÷ Δs (L{L}). Not the contrast z",
  "いまの組": "current set",
  "このスクリーニングの上位({n} ヘッド)": "Top heads of this screening ({n} heads)",
  "このヘッド(L{L} H{h})": "This head (L{L} H{h})",
  "このヘッドの書き込みのうち方向 {d} に沿った成分だけを消す射影(L:Hh:s1@{d})をレシピに足す(s は recipe タブで変えられる)": "Add a projection that removes only the component of this head's write along {d} (L:Hh:s1@{d}) to the recipe (change s in the recipe tab)",
  "このレシピの水準": "this recipe's level",
  "この方式のレシピを recipe タブに読み込む": "Load this method's recipe into the recipe tab",
  "この種類の結果の表示はありません。中身をそのまま出します。": "No view for this kind of result; showing the raw content.",
