  "もう一度押すとレシピから外す(s と方向は recipe タブで変えられる)": "Click again to remove it from the recipe (change s and the direction in the recipe tab)",
  "ニューロンの消去": "neuron ablation",
  "プロンプト": "prompt",
  "ヘッドの丸ごと倍率": "whole-head gain",
  "ヘッドの効率 η {d}(s を上げたときの下がり方 ÷ Δs)": "head efficiency η {d} (drop when s is raised ÷ Δs)",
  "ヘッドの因果の効き {d}(止めたときの下がり方)": "head causal effect {d} (drop when the head is ablated)",
