  "レシピのヘッドの射影(s > 0 = 方向成分を引く、黄 = s < 0 で強める)": "recipe head projections (s > 0 = subtract the direction component; yellow = s < 0, strengthen)",
  "一致 null": "match null",
  "一致減": "match drop",
