  "下がり null": "drop null",
  "下がり方": "drops",
  "下がり方 = 介入の前 − 後の A 側の射影の値(正 = このヘッドが A 側の向きに押していた)。ratio > 1 は間接の経路、< 1 は補い合い。η = いまの組から s を Δs 上げたときの、効きにくい例での下がり方 ÷ Δs。": "Drop = A-side projection before − after the intervention (positive = this head was pushing toward A). ratio > 1 means indirect paths, < 1 means compensation. η = drop on the hard examples when s is raised by Δs from the current set, ÷ Δs.",
  "例ごとの射影の値(L{L}、{n} 件)": "Per-example projections (L{L}, {n} examples)",
  "値 = ヘッドの出力を 0 にしたときの、方向への射影の値の下がり方(射影の値を測る層での最大、causal_max)。対照の z(ヘッドの対照)とは別物": "Value = drop in the projection onto the direction when the head's output is zeroed (max over the layers where the projection is measured, causal_max). Not the head-contrast z",
  "全層の射影消去": "all-layer projection ablation",
  "出力を 0 にしたときの A 側の射影の値の下がり方": "Drop in the A-side projection when the output is zeroed",
  "判定の一致率(%)": "match rate (%)",
  "判定の一致率(無介入 {p})": "match rate (baseline {p})",
  "判定の一致率の減少(無介入 − 介入)": "Drop in the match rate (baseline − intervention)",
  "効率 η(marginal、表示中の測る層)。* = いまの組のヘッド": "Efficiency η (marginal, at the measured layer shown). * = head in the current set",
  "効率(marginal)": "Efficiency (marginal)",
  "合成の構造には direction ビューのデータがありません": "The synthetic structure has no direction view data",
  "同じ方向を、方式ごとに強さ α を合わせて A 側の射影の値を目標までそろえ、副作用を比べる。B ⊥ = 関係のない入力(B 側)の残差の、方向に直交する成分のずれ(小さいほど他を壊さない)。緑の行 = B ⊥ が最も小さい方式。": "Each method's strength α is tuned so the A-side projection reaches the same target along the same direction, then the side effects are compared. B ⊥ = orthogonal drift of the residual on unrelated inputs (B side); smaller breaks less. Green row = smallest B ⊥.",
  "因果スクリーニングはまだありません({cmd})。": "No causal screening yet ({cmd}).",
  "地図: 効き": "map: effect",
  "地図: 効率 η": "map: efficiency η",
  "地図の板の上辺のヘッドを、効率 η で色付けする": "Color the heads on the map's slab edges by efficiency η",
  "地図の板の上辺のヘッドを、止めたときの下がり方(causal_max)で色付けする": "Color the heads on the map's slab edges by the drop when ablated (causal_max)",
  "基準 L{L}": "base L{L}",
