  "基準層の方向との cos(右の目盛り)": "cos with the base layer's direction (right axis)",
  "基準層を L{L} にしました": "base layer set to L{L}",
  "対照集合が見つからないので cohen_d は測れません": "The contrast set is missing, so cohen_d cannot be measured",
  "対照集合の A / B のプロンプトを流して、全層の射影の値を測り直す(モデルを使う。GPU を待つことがあります)": "Run the contrast set's A / B prompts and re-measure the projection at every layer (uses the model; may wait for the GPU)",
  "対照集合の検証プロンプトで性格の判定(validate.match)に当たった割合": "Share of the contrast set's validation prompts that matched the persona check (validate.match)",
  "射影 s1 レシピ": "proj s1 recipe",
  "射影 s: ヘッドが残差に書くベクトルのうち方向 r̂ に沿った成分だけを (1 − s) 倍にする(1 で消す、2 で反転、直交成分はそのまま)。LoRA で当てるので cvec には入りません。3 列チャットの − 列は s が負(その方向へ強める)。": "Projection s: scales only the component along r̂ of what the head writes to the residual by (1 − s) (1 removes it, 2 flips it, the orthogonal part is untouched). Applied as a LoRA, so it is not part of the cvec. The − column of the 3-column chat uses negative s (strengthens along the direction).",
