  "選んだ層を、この方向の基準層(proj の direction_layer: base と、因果スクリーニングで射影の値を測る主の層の既定)として記録する": "Record the chosen layer as this direction's base layer (used by proj direction_layer: base and as the default primary measured layer of causal screening)",
