  // direction ビューの「JSON から方向とヘッドを作る」(head_pipeline)
  "(この実行には最初の組がありません)": "(this run has no initial set)",
  "* = 射影の値を測る主の層。下がり方 = 止める前 − 後の A 側の射影の値(正 = A 側の向きに押していた)。": "* = primary measured layer. Drop = A-side projection before − after ablating (positive = the head was pushing toward A).",
  "1. 方向と基準層": "1. Direction and base layer",
  "2. 因果スクリーニング": "2. Causal screening",
  "3. 最初の比率": "3. Initial ratio",
  "4. 効率での配り直し": "4. Reallocation by efficiency",
  "A と B が同じです(system も recipe も違いがありません)": "A and B are the same (neither the system nor the recipe differs)",
  "A と B で同じ質問を読ませ、層ごとに残差の平均の差を方向にします(質問は全部使う)。cohen_d は、A と B の射影の値(残差 · 方向)がどれだけ離れているか。いちばん離れる層を基準層として記録します。": "A and B read the same questions; the per-layer difference of the mean residuals becomes the direction (all questions are used). cohen_d is how far apart the A and B projections (residual · direction) are. The layer where they are furthest apart is recorded as the base layer.",
  "A と B の作り方がありません: system_a か system_b(片方だけでも可)、recipe_a / recipe_b、または側ごとの質問 prompts_a / prompts_b を書いてください": "No way to make A and B: write system_a or system_b (one is enough), recipe_a / recipe_b, or separate questions in prompts_a / prompts_b",
  "{k} は質問の文字列のリストです": "{k} must be a list of question strings",
  "質問がありません: 両側で同じなら user_prompts、側ごとに違うなら prompts_a と prompts_b を書いてください": "No questions: write user_prompts for questions shared by both sides, or prompts_a and prompts_b for separate ones",
  "A と B で質問が違います。方向には狙った違いのほかに、話題・長さ・言語の差も混ざるので、それ以外はできるだけそろえてください": "A and B use different questions. Differences in topic, length and language also end up in the direction, so keep everything else as similar as you can",
