  "入れる": "insert",
  "同じ JSON・同じ設定で作り済みの方向と因果の結果があっても使い回さず、最初から作り直す(止めて流し直すときは外したままにすると配分からやり直せる)": "Rebuild everything even if the direction and causal results already exist for the same JSON and settings (leave it unchecked when re-running after a stop, so that it resumes from the allocation)",
