  "採点に bench extra が要る": "Grading needs the bench extra.",
  "片方だけ正解: 比較 {a} / 対象 {b}(p = {p})": "right on one side only: reference {a} / target {b} (p = {p})",
  "正答率": "accuracy",
  "答えを取り出せなかった": "no answer found",
  "実地テスト": "field test",
  "実地テスト(本番と同じ動かし方で、ファイルどうしを比べる)": "Field test (run files the way they are really used, and compare them)",
  "本番と同じ動かし方(llama-server、思考あり、サンプリングあり)で、長い作業・ツール呼び出し・質問集・perplexity を測り、ファイルどうしを比べます。eval で見えない、長い思考の途中のループや、ツール呼び出しの崩れを見ます。マージしたファイルもそのまま測れます。走っている間は読み込んでいるモデルを GPU から下ろすので、チャットなどは待たされます。27B で質問集 200 問を足して 1 ファイル 30〜45 分かかります。": "Measures long tasks, tool calling, question sets and perplexity the way a model is really used (llama-server, thinking on, sampling on), and compares files. It catches what eval cannot see, such as loops deep in long reasoning and broken tool calls, and it measures merged files directly. While it runs, the loaded model leaves the GPU, so chat and the like have to wait. A 27B file with 200 extra questions takes 30 to 45 minutes.",
  "測るファイル(GGUF のパス)。空ならいま読んでいるモデル": "File to measure (GGUF path). Empty: the loaded model",
  "測るファイル": "file to measure",
  "比べるファイル(例 元のモデル)。空なら測るだけ": "File to compare with (e.g. the original model). Empty: only measure",
  "比べるファイル": "compare with",
  "空なら比べない": "empty: no comparison",
  "測るファイルに当てる LoRA(パス か パス:倍率)。比べるファイルが空なら、同じファイルの LoRA なしと比べる": "LoRA for the measured file (path or path:scale). With no comparison file, the same file without the LoRA is the comparison",
  "llama-server のパス。空なら GNE_LLAMA_SERVER か PATH から探す": "Path of llama-server. Empty: GNE_LLAMA_SERVER or PATH",
  "空なら自動で探す": "empty: find it",
  "自分の質問集。1 行に 名前=ファイル(JSON か YAML のリスト)。ループ・本文が空・上限で切れた割合を測る": "Your own question sets, one name=file per line (a JSON or YAML list). Measures loops, empty answers and answers cut at the limit",
