  "いまのレシピ({n} ユニット)を {name} で置き換えますか?": "Replace the current recipe ({n} {n|unit|units}) with {name}?",
  "前に測った結果です(A {a} / B {b} 例)。測り直すには「測り直す」": "Result from an earlier run (A {a} / B {b} examples). Press “measure again” to measure anew",
  "強さ {d} でレシピに足す(強さはレシピのパネルで変えられる)": "Add to the recipe with strength {d} (change the strength in the recipe panel)",
  "レシピに足す(+)": "Add to recipe (+)",
  "レシピに足す(−)": "Add to recipe (−)",
  "強さ ×{k} でレシピに足す(専門家が選ばれたときだけ効く。強さはレシピのパネルで変えられる)": "Add to the recipe with strength ×{k} (works only when the expert is chosen; change the strength in the recipe panel)",
