  "強さ ×{k} でレシピに足す(強さはレシピのパネルで変えられる)": "Add to the recipe with strength ×{k} (change the strength in the recipe panel)",
  "もう一度押すとレシピから外す(強さ s と方向はレシピのパネルで変えられる)": "Press again to remove it from the recipe (change the strength s and the direction in the recipe panel)",
  "レシピに足す(射影 s1)": "Add to recipe (projection s1)",
  "このヘッドの書き込みのうち方向 {d} に沿った成分だけを消す射影(L:Hh:s1@{d})をレシピに足す(強さ s はレシピのパネルで変えられる)": "Add the projection that removes only the part of this head's writes along {d} (L:Hh:s1@{d}) to the recipe (change the strength s in the recipe panel)",
  "専門家全体を強さ ×{k} でレシピに足す(強さはレシピのパネルで変えられる)": "Add the whole expert to the recipe with strength ×{k} (change the strength in the recipe panel)",
