  "行の「レシピに足す」で、その層の keyed のユニットをレシピに足す。「key-verify」で LoRA が式どおりに書くかを確かめる": "Use “Add to recipe” on a row to add that layer's keyed unit to the recipe. “key-verify” checks that the LoRA writes as the formula says",
  "このサンプリングをレシピに足す(レシピを保存するとファイルに入る)": "Add this sampling to the recipe (saving the recipe writes it to the file)",
  "合わせた組でレシピを置き換える": "Replace the recipe with the combined set",
