  "ニューロンの強さは rel(その層の残差ノルムの中央値に対する大きさ)。マップに + は黄、− は赤紫の輪で出ます。": "Neuron strength is rel (relative to the median residual norm of the layer). On the map, + shows as a yellow ring and − as magenta.",
  "いまのレシピを当てた応答を、何もしない応答・逆向きに当てた応答と並べて比べます。チャットは「くわしく見る」のニューロンの Chat に開きます。": "Compare responses with the current recipe side by side with no change and with the recipe reversed. The chat opens in the neuron Chat of the details panel.",
  "方向の射影消去: 選んだ方向を残差に書き込む重みから消す(LoRA で当てる)。gne direction で作った方向を使う": "Directional ablation: remove the chosen direction from the weights that write to the residual (applied as a LoRA). Uses a direction made with gne direction",
