  "書き出しはここにまとめています。足す押し方(ニューロン・方向)は cvec、ヘッド・キーつきの書き込みは「LoRA・マージ」、計算で作るニューロン(FiSH)は nw の LoRA です。": "All exports are here. Additive pushes (neurons, directions) go to a cvec, heads and keyed writes to “LoRA / merge”, and computed neurons (FiSH) to an nw LoRA.",
